import React, { Component } from "react";
import "./Contactus.css";
import FormJson from './formid';

export default class Contactus extends Component {
    render() {
        // Move the filtering of FormJson outside of the return statement
        const contactForm = FormJson.filter(item => item.formId === 1);

        return (
            <div className="content-container">
                <div className="rectangle">
                    <h1><a href="/Contact Us" className="contact">Contact Us</a></h1>
                    <p className="foryou">We are here for you!</p>
                    {/* Render the filtered contactForm */}
                    {contactForm.map((item, index) => (
                        <div key={index}>
                            <p className={item.className}>{item.value}</p>
                            <input type={item.type} className={item.className} placeholder={item.placeholder} required />
                        </div>
                    ))}
                </div>
            </div>
        );
    }
}



